/* Every product starts with 10 units in stock. */
PRODUCTS.forEach(function(p) {
    if (typeof p.stock !== 'number') p.stock = 10;
    if (p.category === 'apple') { p.stock = 0; }
    if (p.category === 'cases') {
      p.variants = ['iPhone 11','iPhone 11 Pro','iPhone 11 Pro Max',
        'iPhone 12','iPhone 12 Mini','iPhone 12 Pro','iPhone 12 Pro Max',
        'iPhone 13','iPhone 13 Mini','iPhone 13 Pro','iPhone 13 Pro Max',
        'iPhone 14','iPhone 14 Plus','iPhone 14 Pro','iPhone 14 Pro Max',
        'iPhone 15','iPhone 15 Plus','iPhone 15 Pro','iPhone 15 Pro Max',
        'iPhone 16','iPhone 16 Plus','iPhone 16 Pro','iPhone 16 Pro Max',
        'iPhone 17','iPhone 17 Plus','iPhone 17 Pro','iPhone 17 Pro Max'
      ].map(function(m){ return { model: m, stock: Math.floor(Math.random()*2)+1 }; });
    }
});

/* ===================== Stock system (persisted per-browser via localStorage) =====================
   Stock decreases every time an order is placed at checkout. When a product's stock hits 0 it shows
   "Out of Stock" everywhere (shop grid, category grid, product page) and can no longer be added to cart. */
var STOCK_KEY = 'voltech_stock';

function getStockOverrides() {
    try {
        var raw = localStorage.getItem(STOCK_KEY);
        return raw ? JSON.parse(raw) : {};
    } catch (e) { return {}; }
}

function saveStockOverrides(map) {
    localStorage.setItem(STOCK_KEY, JSON.stringify(map));
}

/* Returns the current remaining stock for a product (defaults to the product's starting stock). */
function getStock(productId) {
    var product = getProductById(productId);
    if (product && product.category === 'apple') { return 0; }
    var overrides = getStockOverrides();
    if (Object.prototype.hasOwnProperty.call(overrides, productId)) {
        return overrides[productId];
    }
    return product ? product.stock : 0;
}

/* Reduces stock by qty (never below 0) and persists it so the product shows "Out of Stock" once depleted. */
function decrementStock(productId, qty) {
    var overrides = getStockOverrides();
    var current = getStock(productId);
    overrides[productId] = Math.max(0, current - qty);
    saveStockOverrides(overrides);
}

