function catIcon(key) { return ICON_SVGS[key] || ICON_SVGS.accessories; }

/* Small "V" bolt brand mark, overlaid bottom-left on product artwork */
function watermarkHTML() {
    return '';
}

function renderStars(rating) {
    var s = '';
    var full = Math.floor(rating);
    var half = rating % 1 >= 0.5 ? 1 : 0;
    var empty = 5 - full - half;
    for (var i = 0; i < full; i++) s += '\u2605';
    for (var i = 0; i < half; i++) s += '\u2605';
    for (var i = 0; i < empty; i++) s += '\u2606';
    return s;
}

function renderProductCard(product) {
    var badgeHtml = product.badge
        ? '<div class="product-badge ' + product.badge + '">' + (product.badge === 'bestseller' ? '\u2605 Best Seller' : product.badge === 'new' ? 'NEW' : 'SALE') + '</div>'
        : '';
    var oldPriceHtml = product.oldPrice
        ? '<span class="price-old">EGP ' + product.oldPrice.toLocaleString() + '</span>'
        : '';
    var conditionHtml = product.condition
        ? '<div class="condition-tag' + (product.condition.indexOf('Used') === 0 ? ' used' : '') + '">' + product.condition + '</div>'
        : '';
    /* Apple category: no star ratings / review counts shown (kept factual, no placeholder review data). */
    var ratingHtml = product.category === 'apple'
        ? ''
        : '<div class="product-rating"><span class="stars">' + renderStars(product.rating) + '</span><span class="rating-text">' + product.rating + ' (' + product.reviews + ')</span></div>';
    var stockHtml = '';
    var stock = getStock(product.id);
    if (stock > 0) {
      stockHtml = '<div class="product-stock in-stock"><span class="stock-dot"></span>In stock</div>';
    } else {
      stockHtml = '<div class="product-stock out-of-stock">Out of Stock</div>';
    }
    var addBtnHtml = stock > 0
        ? '<button class="add-cart-btn" onclick="event.preventDefault();event.stopPropagation();addToCart(' + product.id + ');" title="Add to Cart">+</button>'
        : '<button class="add-cart-btn" disabled title="Out of Stock" style="opacity:.4;cursor:not-allowed;">+</button>';
    return '<a href="product.html?id=' + product.id + '" class="product-card' + (stock <= 0 ? ' is-out-of-stock' : '') + '" style="text-decoration:none;color:inherit;">'
        + badgeHtml
        + (function(){ var img = getProductImage(product.id); return img ? '<div class="product-image" style="padding:0;overflow:hidden;"><img src="' + img + '" alt="' + product.name + '" style="width:100%;height:100%;object-fit:cover;display:block;" onerror="this.parentNode.innerHTML=\'' + product.icon + watermarkHTML() + '\'"/>' + watermarkHTML() + '</div>' : '<div class="product-image">' + product.icon + watermarkHTML() + '</div>'; })()
        + '<div class="product-info">'
        + conditionHtml
        + '<div class="product-category">' + product.categoryLabel + '</div>'
        + '<div class="product-name">' + product.name + '</div>'
        + ratingHtml
        + stockHtml
        + '<div class="product-price"><div><span class="price">EGP ' + product.price.toLocaleString() + '</span>' + oldPriceHtml + '</div>'
        + addBtnHtml + '</div>'
        + '</div></a>';
}

function getUrlParam(name) {
    return new URLSearchParams(window.location.search).get(name);
}

function getProductById(id) {
    for (var i = 0; i < PRODUCTS.length; i++) {
        if (PRODUCTS[i].id === id) return PRODUCTS[i];
    }
    return null;
}

function getRelatedProducts(product) {
    return PRODUCTS.filter(function(p) {
        return p.category === product.category && p.id !== product.id;
    }).slice(0, 4);
}

