function getReviewsForProduct(productId) {
    var seed = productId * 17 + 3;
    function rnd() { seed = (seed * 9301 + 49297) % 233280; return seed / 233280; }
    var count = (productId % 2 === 0) ? 3 : 2;
    var names = REVIEW_NAMES_AR.slice();
    var templates = REVIEW_TEMPLATES_AR.slice();
    var pickedNames = [];
    var pickedTemplates = [];
    for (var i = 0; i < count; i++) {
        var ni = Math.floor(rnd() * names.length);
        pickedNames.push(names.splice(ni, 1)[0]);
        var ti = Math.floor(rnd() * templates.length);
        pickedTemplates.push(templates.splice(ti, 1)[0]);
    }
    var months = ["يناير","فبراير","مارس","أبريل","مايو","يونيو","يوليو","أغسطس"];
    var out = [];
    for (var j = 0; j < count; j++) {
        var day = 3 + Math.floor(rnd() * 25);
        var month = months[Math.floor(rnd() * 6) + 2];
        out.push({
            name: pickedNames[j],
            date: day + " " + month + " 2026",
            rating: pickedTemplates[j].rating,
            title: pickedTemplates[j].title,
            text: pickedTemplates[j].text
        });
    }
    return out;
}

/* ===================== Cart (localStorage) ===================== */
var CART_KEY = 'voltech_cart';

function getCart() {
    try {
        var raw = localStorage.getItem(CART_KEY);
        return raw ? JSON.parse(raw) : [];
    } catch (e) { return []; }
}

function saveCart(cart) {
    localStorage.setItem(CART_KEY, JSON.stringify(cart));
    updateCartCount();
}

function addToCart(productId, qty) {
    qty = qty || 1;
    var stock = getStock(productId);
    if (stock <= 0) {
        showCartToast('Sorry, this product is out of stock');
        return;
    }
    var cart = getCart();
    var existing = cart.find(function(i) { return i.id === productId; });
    var alreadyInCart = existing ? existing.qty : 0;
    var allowedQty = Math.min(qty, Math.max(0, stock - alreadyInCart));
    if (allowedQty <= 0) {
        showCartToast('No more stock available for this product');
        return;
    }
    if (existing) {
        existing.qty += allowedQty;
    } else {
        cart.push({ id: productId, qty: allowedQty });
    }
    saveCart(cart);
    showCartToast(allowedQty < qty ? 'Added only ' + allowedQty + ' (limited stock)' : null);
}

function removeFromCart(productId) {
    var cart = getCart().filter(function(i) { return i.id !== productId; });
    saveCart(cart);
}

function updateCartQty(productId, qty) {
    var cart = getCart();
    var item = cart.find(function(i) { return i.id === productId; });
    if (item) {
        var stock = getStock(productId);
        item.qty = qty;
        if (item.qty < 1) item.qty = 1;
        if (item.qty > 99) item.qty = 99;
        if (item.qty > stock) item.qty = stock;
    }
    saveCart(cart);
}

function getCartCount() {
    return getCart().reduce(function(sum, i) { return sum + i.qty; }, 0);
}

function getCartDetailed() {
    return getCart().map(function(i) {
        var p = getProductById(i.id);
        if (!p) return null;
        return { product: p, qty: i.qty, subtotal: p.price * i.qty };
    }).filter(Boolean);
}

function getCartTotal() {
    return getCartDetailed().reduce(function(sum, i) { return sum + i.subtotal; }, 0);
}

function updateCartCount() {
    var els = document.querySelectorAll('.cart-count');
    var count = getCartCount();
    els.forEach(function(el) { el.textContent = count; });
}

function showCartToast(message) {
    var existing = document.getElementById('cart-toast');
    if (existing) existing.remove();
    var toast = document.createElement('div');
    toast.id = 'cart-toast';
    toast.className = 'cart-toast';
    toast.innerHTML = '&#10003; ' + (message || 'Added to cart');
    document.body.appendChild(toast);
    requestAnimationFrame(function() { toast.classList.add('show'); });
    setTimeout(function() {
        toast.classList.remove('show');
        setTimeout(function() { toast.remove(); }, 300);
    }, 1800);
}

