function defaultAvatarForGender(gender) {
    if (gender === 'male') return DEFAULT_AVATAR_MALE;
    if (gender === 'female') return DEFAULT_AVATAR_FEMALE;
    return DEFAULT_AVATAR_NEUTRAL;
}

function getUserAvatar(user) {
    if (user && user.avatar) return user.avatar;
    return defaultAvatarForGender(user && user.gender);
}

function updateUserProfile(fields) {
    var user = getCurrentUser() || {};
    for (var k in fields) { if (fields.hasOwnProperty(k)) user[k] = fields[k]; }
    setCurrentUser(user);
    return user;
}

/* Saved shipping address, persisted per-account so it's pre-filled next visit/checkout. */
function saveUserAddress(address) {
    return updateUserProfile({ address: address });
}

function getUserAddress() {
    var user = getCurrentUser();
    return (user && user.address) || null;
}

/* Order history, persisted per-account so past purchases are visible after logging back in. */
var ORDERS_KEY = 'voltech_orders';

function saveOrderRecord(order) {
    var user = getCurrentUser();
    if (!user) return;
    var all = [];
    try { all = JSON.parse(localStorage.getItem(ORDERS_KEY)) || []; } catch (e) { all = []; }
    order.email = user.email;
    order.date = new Date().toISOString();
    all.unshift(order);
    localStorage.setItem(ORDERS_KEY, JSON.stringify(all));
}

function getUserOrders() {
    var user = getCurrentUser();
    if (!user) return [];
    var all = [];
    try { all = JSON.parse(localStorage.getItem(ORDERS_KEY)) || []; } catch (e) { all = []; }
    return all.filter(function(o) { return o.email === user.email; });
}

function getLastOrder() {
    var orders = getUserOrders();
    return orders.length ? orders[0] : null;
}

function updateAccountHeaderLink() {
    var el = document.querySelector('.header-btn[href="account.html"]');
    if (!el) return;
    var user = getCurrentUser();
    if (user) {
        var firstName = (user.name || 'Account').split(' ')[0];
        el.innerHTML = '<img src="' + getUserAvatar(user) + '" alt="" style="width:18px;height:18px;border-radius:50%;object-fit:cover;vertical-align:-4px;margin-right:2px;"> ' + firstName;
    }
}

