/* ===================== Search ===================== */
function searchProducts(query) {
    query = (query || '').trim().toLowerCase();
    if (!query) return [];
    return PRODUCTS.filter(function(p) {
        return p.name.toLowerCase().indexOf(query) !== -1
            || p.categoryLabel.toLowerCase().indexOf(query) !== -1
            || p.category.toLowerCase().indexOf(query) !== -1;
    });
}

function initSearchBar() {
    var input = document.getElementById('search-input');
    var btn = document.getElementById('search-btn');
    var dropdown = document.getElementById('search-suggestions');
    if (!input) return;

    function goToSearch() {
        var q = input.value.trim();
        if (q) window.location.href = 'shop.html?search=' + encodeURIComponent(q);
    }

    function renderSuggestions() {
        var q = input.value.trim();
        if (!q) { dropdown.classList.remove('active'); dropdown.innerHTML = ''; return; }
        var results = searchProducts(q).slice(0, 6);
        if (results.length === 0) {
            dropdown.innerHTML = '<div class="search-no-results">No products found for "' + q + '"</div>';
            dropdown.classList.add('active');
            return;
        }
        dropdown.innerHTML = results.map(function(p) {
            return '<a class="search-suggestion-item" href="product.html?id=' + p.id + '">'
                + '<span class="sugg-icon">' + p.icon + '</span>'
                + '<span class="sugg-info"><span class="sugg-name">' + p.name + '</span><span class="sugg-cat">' + p.categoryLabel + ' &middot; EGP ' + p.price.toLocaleString() + '</span></span>'
                + '</a>';
        }).join('') + '<div class="search-see-all" onclick="window.location.href=\'shop.html?search=' + encodeURIComponent(q) + '\'">See all results for "' + q + '" &#8594;</div>';
        dropdown.classList.add('active');
    }

    input.addEventListener('input', renderSuggestions);
    input.addEventListener('keydown', function(e) {
        if (e.key === 'Enter') { e.preventDefault(); goToSearch(); }
        if (e.key === 'Escape') { dropdown.classList.remove('active'); input.blur(); }
    });
    input.addEventListener('focus', function() { if (input.value.trim()) renderSuggestions(); });
    if (btn) btn.addEventListener('click', goToSearch);
    document.addEventListener('click', function(e) {
        if (!input.contains(e.target) && !dropdown.contains(e.target)) {
            dropdown.classList.remove('active');
        }
    });

    var presetQ = getUrlParam('search');
    if (presetQ) input.value = presetQ;
}

document.addEventListener('DOMContentLoaded', function() {
    updateCartCount();
    initSearchBar();
    updateAccountHeaderLink();
    var socialSlot = document.getElementById('header-social-container');
    if (socialSlot) socialSlot.innerHTML = buildSocialLinksHTML();
    initScrollReveal();
});

/* ===================== Scroll reveal + product-card tilt (homepage polish) ===================== */
function initScrollReveal() {
    var targets = document.querySelectorAll('.reveal-on-scroll');
    if (!targets.length) return;
    if (!('IntersectionObserver' in window)) {
        targets.forEach(function(t) { t.classList.add('revealed'); });
        return;
    }
    var io = new IntersectionObserver(function(entries) {
        entries.forEach(function(entry) {
            if (entry.isIntersecting) {
                entry.target.classList.add('revealed');
                io.unobserve(entry.target);
            }
        });
    }, { threshold: 0.12 });
    targets.forEach(function(t) { io.observe(t); });
}

