function getLang() { return localStorage.getItem(LANG_KEY) || 'en'; }

function toggleLanguage() {
  var next = getLang() === 'en' ? 'ar' : 'en';
  localStorage.setItem(LANG_KEY, next);
  applyLanguage();
  location.reload();
}

function t(key) {
  var lang = getLang();
  return (TRANSLATIONS[lang] && TRANSLATIONS[lang][key]) || key;
}

function applyLanguage() {
  var lang = getLang();
  var lbl = document.getElementById('lang-toggle-label');
  if (lang === 'ar') {
    document.documentElement.lang = 'ar';
    document.documentElement.dir = 'rtl';
    if (lbl) lbl.textContent = 'English';
  } else {
    document.documentElement.lang = 'en';
    document.documentElement.dir = 'ltr';
    if (lbl) lbl.innerHTML = '\u0639\u0631\u0628\u064A';
  }
  // Translate static data-translate elements
  document.querySelectorAll('[data-translate]').forEach(function(el) {
    var key = el.getAttribute('data-translate');
    el.textContent = t(key);
  });
  // Translate placeholders
  document.querySelectorAll('[data-translate-placeholder]').forEach(function(el) {
    var key = el.getAttribute('data-translate-placeholder');
    el.placeholder = t(key);
  });
}

document.addEventListener('DOMContentLoaded', applyLanguage);
// ── Theme Toggle ──────────────────────────────────────────────
var THEME_KEY = 'voltech_theme';
function getTheme() { return localStorage.getItem(THEME_KEY) || 'dark'; }
function toggleTheme() {
  var next = getTheme() === 'dark' ? 'light' : 'dark';
  localStorage.setItem(THEME_KEY, next);
  applyTheme();
}
function applyTheme() {
  var theme = getTheme();
  if (theme === 'light') {
    document.body.classList.add('light-mode');
  } else {
    document.body.classList.remove('light-mode');
  }
  var darkIcon = document.getElementById('theme-icon-dark');
  var lightIcon = document.getElementById('theme-icon-light');
  if (darkIcon && lightIcon) {
    darkIcon.style.display  = theme === 'light' ? 'none'   : 'inline';
    lightIcon.style.display = theme === 'light' ? 'inline' : 'none';
  }
}
document.addEventListener('DOMContentLoaded', applyTheme);
